from collections import Counter,deque
def comps(g,val,conn=8):
    seen=set(); out=[]
    nb=[(dy,dx) for dy in(-1,0,1) for dx in(-1,0,1) if (dy or dx)]
    H,W=len(g),len(g[0])
    for i in range(H):
        for j in range(W):
            if g[i][j]==val and (i,j) not in seen:
                q=deque([(i,j)]); seen.add((i,j)); c=[]
                while q:
                    y,x=q.popleft(); c.append((y,x))
                    for dy,dx in nb:
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and g[ny][nx]==val and (ny,nx) not in seen:
                            seen.add((ny,nx)); q.append((ny,nx))
                out.append(c)
